package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of an owner "household": owners sharing the same last name and
 * postcode. The last name is compared case-insensitively with runs of whitespace collapsed
 * to a single space; the postcode is taken as stored. Provides the deterministic identifier
 * shared by the household.
 *
 * <p>The identifier is derived deterministically from the normalized last name and postcode
 * — the first 12 upper-case hex characters of SHA-256 over {@code normalizedLastName + '|' +
 * postcode} — so every owner with the same last name and postcode resolves to the same value
 * regardless of creation order, and no owner-to-owner linking is needed.
 *
 * @see AssignHousehold stamps each owner with its computed identifier.
 * @see EnsureUniqueIdentity blocks a second owner in the same household unless it opts in.
 */
final class Household {

    /** Length of the household identifier, in hex characters. */
    private static final int ID_LENGTH = 12;

    private Household() {
    }

    /** The stable identifier shared by every owner in the household keyed by {@code lastName}
     *  and {@code postcode}. */
    static String id(String lastName, String postcode) {
        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
        return Sha256.hex(key, ID_LENGTH);
    }

    /** How many of the given owners belong to the household with {@code householdId}. Owners with a
     *  null or non-matching {@code householdId} are not counted; a null {@code householdId} yields 0. */
    static long size(String householdId, Iterable<Owner> owners) {
        if (householdId == null) {
            return 0;
        }
        long count = 0;
        for (Owner owner : owners) {
            if (householdId.equals(owner.getHouseholdId())) {
                count++;
            }
        }
        return count;
    }

    /** A last name trimmed and lower-cased, with internal whitespace runs collapsed to a single space. */
    private static String normalizeName(String value) {
        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
=== MembershipPoints.java ===
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * The membership points system. An owner's score starts at 0 and gains points for the
 * factors below; the score then maps to a membership level. The single place these rules
 * live, keeping {@link AssignMembershipLevel} to orchestration.
 *
 * <ul>
 *   <li>+2 when an email is on file,</li>
 *   <li>+1 when the owner has no namesakes ({@code namesakeCount} is 0),</li>
 *   <li>+2 for a household of {@value #LARGE_HOUSEHOLD_SIZE} or more,</li>
 *   <li>+3 for tenure over {@value #LONG_TENURE_FISCAL_YEARS} fiscal year.</li>
 * </ul>
 *
 * The resulting points map to a level: 1 for 0-1, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
 */
final class MembershipPoints {

    private static final int EMAIL_POINTS = 2;
    private static final int NO_NAMESAKES_POINTS = 1;
    private static final int LARGE_HOUSEHOLD_POINTS = 2;
    private static final int LONG_TENURE_POINTS = 3;

    /** Smallest household size that earns the household points. */
    private static final int LARGE_HOUSEHOLD_SIZE = 3;
    /** Tenure, in whole fiscal years, that must be exceeded to earn the tenure points. */
    private static final long LONG_TENURE_FISCAL_YEARS = 1;

    private MembershipPoints() {
    }

    /** The owner's membership score from its factors. */
    static int score(String email, Integer namesakeCount, long householdSize, long tenureFiscalYears) {
        int points = 0;
        if (email != null && !email.isBlank()) {
            points += EMAIL_POINTS;
        }
        if (namesakeCount != null && namesakeCount == 0) {
            points += NO_NAMESAKES_POINTS;
        }
        if (householdSize >= LARGE_HOUSEHOLD_SIZE) {
            points += LARGE_HOUSEHOLD_POINTS;
        }
        if (tenureFiscalYears > LONG_TENURE_FISCAL_YEARS) {
            points += LONG_TENURE_POINTS;
        }
        return points;
    }

    /** The membership level a score maps to: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6+). */
    static int level(int points) {
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }
}

