package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Step of {@code POST /api/owners}: records whether the new owner is a possible duplicate of
 * an existing one — sharing the same last name and postcode but a different telephone (see
 * {@link PossibleDuplicate}). Such an owner is still created; the matching owner's id is
 * stored in {@code possibleDuplicateOf} so a later read can flag it.
 *
 * <p>Runs after {@link EnsureUniqueIdentity} has already rejected household duplicates, so a
 * match reaching here can only be a declared household member ({@code sharesHousehold}). A
 * declared member is not a suspected duplicate, so it is never flagged; otherwise the
 * earliest-created (lowest id) matching owner is recorded, and no match leaves the field unset.
 */
public class FlagPossibleDuplicate {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            owner.setPossibleDuplicateOf(null); // a declared household member is not a suspected duplicate
            return;
        }
        Integer matchId = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.isDeleted()) {
                continue; // a soft-deleted owner is not a duplicate to flag against
            }
            if (PossibleDuplicate.matches(existing, owner)) {
                Integer id = existing.getId();
                if (id != null && (matchId == null || id < matchId)) {
                    matchId = id;
                }
            }
        }
        owner.setPossibleDuplicateOf(matchId);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of an owner's <em>identity key</em>: the value that decides when
 * two owners are the same person. It joins the owner's normalized telephone, email and
 * household identifier into one string, so a duplicate is an exact match of the whole key
 * rather than of any single field.
 *
 * <p>Key = {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}.
 * All three parts are already stored in canonical form ({@link NormalizeOwnerTelephone}
 * stores the E.164 telephone, {@link NormalizeOwnerEmail} the lower-cased email and
 * {@link AssignHousehold} the deterministic household id), so the key is built from the
 * owner's stored fields; email is lower-cased defensively so the comparison is
 * case-insensitive.
 *
 * <p>Exposed as a derived, read-only owner field. The create endpoint's duplicate block is
 * keyed on the {@code householdId} alone (see {@link EnsureUniqueIdentity}); this fuller key
 * is retained only for display.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    /** The identity key of an existing owner, derived from its stored fields. */
    public static String of(Owner owner) {
        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    /** The identity key for the given normalized telephone, email and household id. */
    public static String of(String telephone, String email, String householdId) {
        return part(telephone) + "|" + lowerCased(email) + "|" + part(householdId);
    }

    /** A field value, or the empty string when absent. */
    private static String part(String value) {
        return value == null ? "" : value;
    }

    /** An email lower-cased, or the empty string when absent. */
    private static String lowerCased(String email) {
        return email == null ? "" : email.toLowerCase(Locale.ROOT);
    }
}
